"use strict";(self.webpackChunksummerz=self.webpackChunksummerz||[]).push([[777705],{517633:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>c,frontMatter:()=>i,metadata:()=>a,toc:()=>l});var s=n(474848),o=n(28453);const i={slug:"2009/01/11",title:"(\uae30\uc0ac) \uc5d0\ub9ad \uc288\ubbf8\uce20\ub294 \uad6c\uae00\uc774 \uc2e0\ubb38\uc0ac\ub4e4\uc744 \uad6c\ud560 \uc218 \uc788\uae38 \uc6d0\ud55c\ub2e4.",date:new Date("2009-01-11T00:45:58.000Z"),authors:"summerz",tags:["media & world","\uc778\ud130\ubdf0","\uad6c\uae00","\uc800\ub110\ub9ac\uc998","\uc2e0\ubb38\uc0ac"]},r=void 0,a={permalink:"/blog/2009/01/11",source:"@site/blog/2009/01/2009-01-11/index.md",title:"(\uae30\uc0ac) \uc5d0\ub9ad \uc288\ubbf8\uce20\ub294 \uad6c\uae00\uc774 \uc2e0\ubb38\uc0ac\ub4e4\uc744 \uad6c\ud560 \uc218 \uc788\uae38 \uc6d0\ud55c\ub2e4.",description:"\uc6d0\ubb38 \ucd9c\ucc98 : CNN Money - Eric Schmidt wishes Google could save newspapers - Jan. 7, 2009",date:"2009-01-11T00:45:58.000Z",tags:[{inline:!0,label:"media & world",permalink:"/blog/tags/media-world"},{inline:!0,label:"\uc778\ud130\ubdf0",permalink:"/blog/tags/\uc778\ud130\ubdf0"},{inline:!0,label:"\uad6c\uae00",permalink:"/blog/tags/\uad6c\uae00"},{inline:!0,label:"\uc800\ub110\ub9ac\uc998",permalink:"/blog/tags/\uc800\ub110\ub9ac\uc998"},{inline:!0,label:"\uc2e0\ubb38\uc0ac",permalink:"/blog/tags/\uc2e0\ubb38\uc0ac"}],readingTime:15.12,hasTruncateMarker:!0,authors:[{name:"summerz",imageURL:"https://github.com/summerz.png",key:"summerz"}],frontMatter:{slug:"2009/01/11",title:"(\uae30\uc0ac) \uc5d0\ub9ad \uc288\ubbf8\uce20\ub294 \uad6c\uae00\uc774 \uc2e0\ubb38\uc0ac\ub4e4\uc744 \uad6c\ud560 \uc218 \uc788\uae38 \uc6d0\ud55c\ub2e4.",date:"2009-01-11T00:45:58.000Z",authors:"summerz",tags:["media & world","\uc778\ud130\ubdf0","\uad6c\uae00","\uc800\ub110\ub9ac\uc998","\uc2e0\ubb38\uc0ac"]},unlisted:!1,prevItem:{title:"2008\ub144 \uc5b4\ucfe0\uc2a4\ud2f1 \ub9c8\uc778\ub4dc \uc120\uc815 10\ub300 \ub274\uc2a4",permalink:"/blog/2009/01/13"},nextItem:{title:"\uad6c\uae00 \ud30c\ube44\ucf58\uc774 \ubc14\ub00c\uc5c8\ub124\uc694.",permalink:"/blog/2009/01/11-2"}},h={authorsImageUrls:[void 0]},l=[];function d(e){const t={a:"a",br:"br",p:"p",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsxs)(t.p,{children:["\uc6d0\ubb38 \ucd9c\ucc98 : ",(0,s.jsx)(t.a,{href:"http://money.cnn.com/2009/01/07/technology/lashinsky_google.fortune/index.htm?postversion=2009010711",children:"CNN Money - Eric Schmidt wishes Google could save newspapers - Jan. 7, 2009"})]}),"\n",(0,s.jsx)(t.p,{children:"(Fortune Magazine) -- Metaphorically speaking, Google is killing the newspaper industry. Online news is quickly hollowing out the traditional paper - the Christian Science Monitor eliminates its print edition, Tribune Co. declares bankruptcy, Detroit's two dailies slash home delivery to three days a week - while Google rakes in advertising profits."}),"\n",(0,s.jsx)(t.p,{children:"(\ud3ec\ucd98 \ub9e4\uac70\uc9c4) -- \ube44\uc720\uc801\uc73c\ub85c \ub9d0\ud574\uc790\uba74 \uad6c\uae00\uc740 \uc2e0\ubb38\uc0b0\uc5c5\uc744 \uc8fd\uc774\uace0 \uc788\ub2e4. \uc628\ub77c\uc778 \ub274\uc2a4\ub294 \uc804\ud1b5\uc801\uc778 \uc885\uc774\uc2e0\ubb38\uc744 \ud669\ud3d0\ud654\uc2dc\ud0a4\uace0 \uc788\ub2e4 - \ud06c\ub9ac\uc2a4\ucc9c \uc0ac\uc774\uc5b8\uc2a4 \ubaa8\ub2c8\ud130\ub294 \uc885\uc774 \uc778\uc1c4\ub97c \uc911\uc9c0\uc2dc\ucf30\uace0, \ud2b8\ub9ac\ubdf4\uc740 \ud30c\uc0b0\uc744 \uc120\uc5b8\ud588\uace0, \ub514\ud2b8\ub85c\uc774\ud2b8\uc758 \ub450 \uac1c\uc758 \uc77c\uac04 \uc2e0\ubb38\uc740 \uc77c\uc8fc\uc77c\uc5d0 3\uc77c\ub9cc \uc2e0\ubb38\uc744 \ubc30\ud3ec\ud558\uae30\ub85c \ud588\ub2e4 - \uad6c\uae00\uc774 \uad11\uace0 \uc218\uc775\uc744 \uae01\uc5b4\ubaa8\uc73c\uace0 \uc788\ub294 \ub3d9\uc548\uc5d0 \ub9d0\uc774\ub2e4."}),"\n",(0,s.jsx)(t.p,{children:"Turns out that Google CEO Eric Schmidt professes a passionate desire to lend a hand. In an interview with Fortune's Adam Lashinsky, he shares some thoughts on how newspapers might yet survive - and how Google (GOOG, Fortune 500) might help."}),"\n",(0,s.jsx)(t.p,{children:"\uad6c\uae00 CEO \uc5d0\ub9ad \uc288\ubbf8\uce20\ub294 \ub3c4\uc6c0\uc744 \uc8fc\uace0 \uc2f6\ub2e4\ub294 \uac15\ud55c \uc758\uc9c0\ub97c \uace0\ubc31\ud55c \uac78\ub85c \ubc1d\ud600\uc84c\ub2e4. \ud3ec\ucd98\uc9c0\uc758 \uc560\ub364 \ub798\uc2e0\uc2a4\ud0a4\uc640\uc758 \uc778\ud130\ubdf0\uc5d0\uc11c \uadf8\ub294 \uc2e0\ubb38\uc0ac\ub4e4\uc774 \uc0b4\uc544\ub0a8\ub294 \ubc29\ubc95\uacfc - \uad6c\uae00\uc774 \ub3c4\uc6b8 \uc218 \uc788\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574 \uc774\uc57c\uae30\ud588\ub2e4."}),"\n",(0,s.jsx)(t.p,{children:"Is there some grand gesture Google can make to solve the newspaper industry's problems?"}),"\n",(0,s.jsx)(t.p,{children:"\uc2e0\ubb38\uc0b0\uc5c5\uc758 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574 \uad6c\uae00\uc774 \ud070 \uc81c\uc548\uc744 \ud560 \uc0dd\uac01\uc774 \uc788\ub294\uac00?"}),"\n",(0,s.jsx)(t.p,{children:"It's not obvious what the grand gesture would be. Google can't make the cost of newsprint go down. We also can't materially change the way consumers behave, and consumers are in fact moving their lives online. We have been able to send clicks to their Web sites, which they can monetize. So that provides some revenue. The problem is that doesn't provide enough revenue to offset the loss of the other revenue."}),"\n",(0,s.jsx)(t.p,{children:"\ud070 \uc81c\uc548\uc774 \uc788\uc744\uc9c0\ub294 \ubd88\ud22c\uba85\ud558\ub2e4. \uad6c\uae00\uc774 \uc885\uc774\uc2e0\ubb38\uc744 \uc1e0\ud1f4\uc2dc\ud0a4\ub294\ub370 \ube44\uc6a9\uc744 \ub4e4\uc77c \uc218\uac00 (\ub4e4\uc77c \ub9ac\uac00) \uc5c6\ub2e4. \ub610\ud55c \uc18c\ube44\uc790\ub4e4\uc774 \ud589\ub3d9\ud558\ub294 \ubc29\uc2dd\uc744 \ubc14\uafc0 \uc218\ub3c4 \uc5c6\ub2e4. \uadf8\ub9ac\uace0 \uc0ac\uc2e4 \uc18c\ube44\uc790\ub4e4\uc774 \uadf8\ub4e4\uc758 \uc0b6\uc744 \uc628\ub77c\uc778 \ucabd\uc73c\ub85c \uc774\ub3d9\uc2dc\ud0a4\uace0 \uc788\ub2e4. \uc6b0\ub9ac\ub294 \uadf8\ub4e4\uc774 \ud074\ub9ad\ud558\uba74 \uc2e0\ubb38\uc0ac\ub4e4\uc758 \uc6f9 \uc0ac\uc774\ud2b8\ub85c \ub118\uaca8\uc8fc\ub294 \uc77c\ub4e4\uc744 \ud560 \uc218 \uc788\uc5c8\uace0, \uc2e0\ubb38\uc0ac\ub4e4\uc740 \uadf8\uac78 \uc218\uc775\uc73c\ub85c \ub9cc\ub4e4 \uc218 \uc788\uc5c8\ub2e4. \uadf8\ub798\uc11c \uc218\uc775\ubd84\uc744 \uc92c\ub2e4. \ubb38\uc81c\ub294 \uc774 \uc218\uc775\uc774 \ub2e4\ub978 \uacf3\uc5d0\uc11c \uc904\uc5b4\ub4dc\ub294 \uc218\uc775\uc744 \ub300\uccb4\ud560 \ub9cc\ud07c \ucda9\ubd84\ud558\uc9c0 \ubabb\ud588\ub2e4\ub294 \uac83\uc774\ub2e4."}),"\n",(0,s.jsx)(t.p,{children:"Maybe their time has just come and gone?"}),"\n",(0,s.jsx)(t.p,{children:"\ud639\uc2dc \uc2e0\ubb38\uc0ac\ub4e4\uc758 \uc2dc\ub300\uac00 \uc9c0\ub098\uac00\ub294 \uac83 \uc544\ub2cc\uac00?"}),"\n",(0,s.jsx)(t.p,{children:"No. They don't have a problem of demand for their product, the news. People love the news. They love reading, discussing it, adding to it, annotating it. The Internet has made the news more accessible. There's a problem with advertising, classifieds and the cost itself of a newspaper: physical printing, delivery and so on. And so the business model gets squeezed."}),"\n",(0,s.jsx)(t.p,{children:"\uc544\ub2c8\ub2e4. \uadf8\ub4e4\uc740 \uadf8\ub4e4\uc758 \uc0dd\uc0b0\ud488\uc778 \ub274\uc2a4\uc5d0 \ub300\ud574\uc11c \ubb38\uc81c\uc810\uc744 \uac00\uc9c0\uace0 \uc788\uc9c0 \uc54a\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \ub274\uc2a4\ub97c \uc88b\uc544\ud55c\ub2e4. \uc0ac\ub78c\ub4e4\uc740 \ub274\uc2a4\ub97c \uc77d\uace0 \ud1a0\ub860\ud558\uace0 \ub367\ubd99\uc774\uace0 \uc8fc\uc11d\ub2e4\ub294 \uac78 \uc88b\uc544\ud55c\ub2e4. \uc778\ud130\ub137\uc740 \ub274\uc2a4\ub97c \ub354\uc6b1 \uc811\uc18d\uc774 \uc6a9\uc774\ud558\uac8c \ub9cc\ub4e4\uc5c8\ub2e4. \ubb38\uc81c\ub294 \uc885\uc774\uc2e0\ubb38\uc758 \uad11\uace0\uc640 \uc2e0\ubb38\uc81c\uc791\uc5d0 \ub4dc\ub294 \ube44\uc6a9\uc5d0 \uc788\ub2e4: \uc778\uc1c4, \ubc30\ub2ec \ub4f1 \ub9d0\uc774\ub2e4. \uadf8\ub9ac\uace0 \ube44\uc988\ub2c8\uc2a4 \ubaa8\ub378\uc740 \uc5f4\uc545\ud574\uc9c0\uace0 \uc788\ub2e4."}),"\n",(0,s.jsx)(t.p,{children:"So what else can Google do?"}),"\n",(0,s.jsx)(t.p,{children:"\uadf8\ub7fc \uadf8 \uc678\uc5d0 \uad6c\uae00\uc774 \ud560 \uc218 \uc788\ub294 \uac8c \uc788\ub294\uac00?"}),"\n",(0,s.jsx)(t.p,{children:"We have a mechanism that enhances online subscriptions, but part of the reason it doesn't take off is that the culture of the Internet is that information wants to be free. We've tried to get newspapers to have more tightly integrated products with ours. We'd like to help them better monetize their customer base. We have tools that make that easier. I wish I had a brilliant idea, but I don't. These little things help, but they don't fundamentally solve the problem."}),"\n",(0,s.jsx)(t.p,{children:"\uc6b0\ub9ac\ub294 \uc628\ub77c\uc778 \uad6c\ub3c5\uc744 \ub298\ub9ac\uac8c \ud558\ub294 \ubc29\ubc95\uc744 \uac00\uc9c0\uace0 \uc788\ub2e4. \uadf8\ub7ec\ub098, \uadf8\uac8c \uc2e4\ud589\ub418\uc9c0 \ubabb\ud558\ub294 \uc774\uc720 \uc911\uc758 \ud558\ub098\ub294 \ubb34\ub8cc\ub97c \uc6d0\ud558\ub294 \uc778\ud130\ub137 \ubb38\ud654 \ub54c\ubb38\uc774\ub2e4. \uc6b0\ub9ac\ub294 \uad6c\uae00\uc758 \uc11c\ube44\uc2a4\ub4e4\uacfc \ub274\uc2a4\ub97c \ub354\uc6b1 \uac00\uae5d\uac8c \ud1b5\ud569\uc2dc\ud0a4\ub824\uace0 \ub178\ub825\ud574\uc654\ub2e4. \uc6b0\ub9ac\ub294 \uc2e0\ubb38\uc0ac\ub4e4\uc774 \uadf8\ub4e4\uc758 \uad6c\ub3c5\uc790\ub4e4\uc744 \uae30\ubc18\uc73c\ub85c \uc218\uc775\uc744 \ub0b4\uac8c \ub3d5\uace0 \uc2f6\ub2e4. \uc6b0\ub9ac\ub294 \uadf8\uac83\uc744 \ub354\uc6b1 \uc27d\uac8c \ud558\ub294 \ud234\uc744 \uac00\uc9c0\uace0 \uc788\ub2e4. \ub0b4\uac8c \ub9e4\uc6b0 \ub180\ub77c\uc6b4 \uc544\uc774\ub514\uc5b4\uac00 \uc788\uc73c\uba74 \uc88b\uaca0\uc9c0\ub9cc \uadf8\ub7f0 \uac74 \uc5c6\ub2e4. \uc6b0\ub9ac\uc758 \uc791\uc740 \ub3c4\uc6c0\ub4e4\uc740 \uc788\uaca0\uc9c0\ub9cc \uadf8\ub4e4\uc740 \uadfc\ubcf8\uc801\uc73c\ub85c \ubb38\uc81c\ub97c \ud480\uc9c0 \ubabb\ud558\uace0 \uc788\ub2e4."}),"\n",(0,s.jsx)(t.p,{children:"How about just buying them?"}),"\n",(0,s.jsx)(t.p,{children:"\uc2e0\ubb38\uc0ac\ub4e4\uc744 \uc778\uc218\ud558\ub294 \uac74 \uc5b4\ub5a4\uac00?"}),"\n",(0,s.jsx)(t.p,{children:"The good news is we could purchase them. We have the cash. But I don't think our purchasing a newspaper would solve the business problems. It would help solidify the ownership structure, but it doesn't solve the underlying problem in the business. Until we can answer that question we're in this uncomfortable conversation."}),"\n",(0,s.jsx)(t.p,{children:"\ub2e4\ud589\uc778 \uac74 \uc6b0\ub9ac\uac00 \uadf8\ub4e4\uc744 \uc778\uc218\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc774\ub2e4. \uc6b0\ub9ac\ub294 \uc790\ubcf8\uc774 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc6b0\ub9ac\uac00 \uc2e0\ubb38\uc0ac\ub97c \uc778\uc218\ud558\ub294 \uac83\uc774 \ube44\uc988\ub2c8\uc2a4\uc801\uc778 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\uace0 \uc0dd\uac01\ud55c\ub2e4. \uc9c0\ubc30\uad6c\uc870\ub97c \uac15\ud654\ud558\ub294\ub370 \ub3c4\uc6c0\uc740 \ub418\uaca0\uc9c0\ub9cc \uc774 \uc0ac\uc5c5 \uae30\uc800\uc5d0 \ud750\ub974\ub294 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uc9c0\ub294 \ubabb\ud55c\ub2e4. \uc6b0\ub9ac\uac00 \uc774 \uc9c8\ubb38\uc5d0 \ub300\ub2f5\ud560 \uc218 \uc788\uc744 \ub54c\uae4c\uc9c0 \uc6b0\ub9ac\ub294 \ubd88\ud3b8\ud55c \ub300\ud654\ub97c \ud574\uc57c \ud55c\ub2e4."}),"\n",(0,s.jsx)(t.p,{children:"I think the solution is tighter integration. In other words, we can do this without making an acquisition. The term I've been using is 'merge without merging.' The Web allows you to do that, where you can get the Web systems of both organizations fairly well integrated, and you don't have to do it on exclusive basis."}),"\n",(0,s.jsx)(t.p,{children:"\ud574\uacb0 \ubc29\ubc95\uc740 \ub354 \ubc00\ucc29\ub41c \ud1b5\ud569\uc744 \ud558\ub294 \uac83\uc774\ub77c \uc0dd\uac01\ud55c\ub2e4. \ub2e4\uc2dc \ub9d0\ud558\uc790\uba74, \uc778\uc218\ub97c \ud558\uc9c0 \uc54a\uace0\ub3c4 \ud560 \uc218 \uc788\ub2e4. \ub0b4\uac00 \uc0ac\uc6a9\ud574\uc628 \uc6a9\uc5b4\ub294 '\ud569\ubcd1 \uc5c6\ub294 \ud569\ubcd1'\uc774\ub2e4. \uc6f9\uc740 \uadf8\uac78 \uac00\ub2a5\ud558\uac8c \ud558\uace0, \uc2e0\ubb38\uc0ac\ub4e4\uc740 \ucda9\ubd84\ud788 \uc798 \ud1b5\ud569\ub41c \uad6c\uc131\ub41c \uc6f9 \uc2dc\uc2a4\ud15c\uc744 \uc5bb\uc744 \uc218 \uc788\uace0, \uadf8\uac83\ub9cc \ud558\ub77c\ub294 \uac83\ub3c4 \uc544\ub2c8\ub2e4."}),"\n",(0,s.jsx)(t.p,{children:"If not buy, how about just pump some cash into them, the way Microsoft famously once did with Apple?"}),"\n",(0,s.jsx)(t.p,{children:"\ub9cc\uc57d \uc778\uc218\ud558\uc9c0 \uc54a\ub294\ub2e4\uba74 \uadf8\ub4e4\uc5d0\uac8c \uc790\uae08\uc744 \ub300\ub294 \uac83\uc740 \uc5b4\ub5a4\uac00? \ub9c8\uc774\ud06c\ub85c \uc18c\ud504\ud2b8\uac00 \uc560\ud50c\uc5d0\uac8c \ud588\ub358 \uac83\ucc98\ub7fc \ub9d0\uc774\ub2e4."}),"\n",(0,s.jsx)(t.p,{children:"There are no current plans to do that. The necessary criteria to get us to make that decision are not currently in place."}),"\n",(0,s.jsx)(t.p,{children:"\ud604\uc7ac \uadf8\ub7f0 \uacc4\ud68d\uc740 \uc5c6\ub2e4. \uc6b0\ub9ac\uac00 \uadf8\ub7f0 \uacb0\uc815\uc744 \ub0b4\ub9ac\ub294\ub370 \ud544\uc694\ud55c \uae30\uc900\uc740 \ud604\uc7ac \uc5c6\ub2e4."}),"\n",(0,s.jsx)(t.p,{children:"Are there other types of structural solutions that are possible?"}),"\n",(0,s.jsx)(t.p,{children:"\ub2e4\ub978 \uc885\ub958\uc758 \uad6c\uc870\uc801\uc778 \ud574\uacb0\ucc45\uc740 \uc5c6\ub294\uac00?"}),"\n",(0,s.jsx)(t.p,{children:"Well, today you have these for-profit companies that are in a terrible business situation who support an important public good. What's an alternative way to support the public good? One is Pro Publica [the non-profit investigative journalism organization headed by former Wall Street Journal Managing Editor Paul Steiger and funded by, among others, the Sandler Foundation]. Plus there'll be consolidation. One scenario says newspapers become part of larger companies. [The Washington Post, for example, is part of a company that makes a considerable portion of its money in the education business]. They're clearly not going to fold because their value is too large."}),"\n",(0,s.jsx)(t.p,{children:"\uae00\uc384, \uc624\ub298\ub0a0 \uc774\ubbf8 \uc138\uc0c1\uc5d4 \uc5f4\uc545\ud55c \ube44\uc988\ub2c8\uc2a4 \ud658\uacbd\uc5d0\uc11c \ubbf8\ub798\uc758 \uc218\uc775\uc744 \ubc14\ub77c\ubcf4\uba70 \uc911\uc694\ud55c \uacf5\uc775\uc744 \uc704\ud558\ub294 \ud68c\uc0ac\ub4e4\uc774 \uc788\ub2e4. \uadf8 \uc678\uc5d0 \uacf5\uc775\uc744 \uc9c0\uc9c0\ud558\ub294 \ub2e4\ub978 \ubc29\ubc95\uc73c\ub85c\ub294 \ubb50\uac00 \uc788\uc744\uae4c? \ud558\ub098\ub294 \ud504\ub85c \ud37c\ube14\ub9ac\uce74 [\ube44\uc5f4\ub9ac \ud0d0\uc0ac \uc800\ub110\ub9ac\uc998 \uc870\uc9c1\uc73c\ub85c \uc804\uc9c1 \uc6d4 \uc2a4\ud2b8\ub9ac\ud2b8 \uc800\ub110 \ub9e4\ub2c8\uc9d5 \uc5d0\ub514\ud130 \ud3f4 \uc2a4\ud14c\uc774\uac70\uac00 \uc774\ub04c\uba70 \uc0cc\ub4e4\ub7ec \ud30c\uc6b4\ub370\uc774\uc158 \ub4f1\uc5d0 \uc758\ud574 \ud22c\uc7a1\ubc1b\uc558\uc74c] \uac00 \uc788\ub2e4. \uadf8\uac83\uc740 \uac15\ud654\ub420 \uac83\uc774\ub2e4. \ub2e4\ub978 \uac00\uc124\uc740 \uc2e0\ubb38\uc0ac\uac00 \ub354 \ud070 \ud68c\uc0ac\uc758 \uc77c\ubd80\uac00 \ub418\ub294 \uac83\uc774\ub2e4. [\uc608\ub97c \ub4e4\uba74 \uc6cc\uc2f1\ud134 \ud3ec\uc2a4\ud2b8\ub294 \uad50\uc721 \ube44\uc988\ub2c8\uc2a4\uc5d0 \uc0c1\ub2f9\ud55c \uc608\uc0b0\uc744 \ub4e4\uc774\ub294 \ud68c\uc0ac\uc758 \uc77c\ubd80\uac00 \ub418\uc5c8\uc74c]. \uadf8\ub4e4\uc740 \uaebe\uc774\uc9c0 \uc54a\uc744 \uac83\uc774\ub2e4. \uc65c\ub098\uba74 \uadf8 \uac00\uce58\uac00 \ub9e4\uc6b0 \ud06c\uae30 \ub54c\ubb38\uc774\ub2e4."}),"\n",(0,s.jsx)(t.p,{children:"What about Google.org, Google's for-profit philanthropic arm, which is investing in alternative-energy startups?"}),"\n",(0,s.jsx)(t.p,{children:"Google.org \ub294 \uc5b4\ub5a4\uac00? \uad6c\uae00\uc758 \uc601\ub9ac\ub97c \ucd94\uad6c\ud558\uba74\uc11c\ub3c4 \uc790\uc120\uc801\uc778 \ub3c4\uc6c0 \uc989 \ub300\uc548\uc801\uc778 \uc2a4\ud0c0\ud2b8\uc5c5 \uae30\uc5c5\ub4e4\uc5d0\uac8c \ud22c\uc790\ud558\ub294 \ub2e8\uccb4 \ub9d0\uc774\ub2e4."}),"\n",(0,s.jsx)(t.p,{children:"We didn't want to co-mingle philanthropy with business. We are in the advertising business."}),"\n",(0,s.jsx)(t.p,{children:"\uc6b0\ub9ac\ub294 \uc790\uc120\uc801\uc778 \uac83\uacfc \ube44\uc988\ub2c8\uc2a4\ub97c \uc11e\uace0 \uc2f6\uc9c0 \uc54a\ub2e4. \uc6b0\ub9ac\ub294 \uad11\uace0 \ube44\uc988\ub2c8\uc2a4\ub97c \ud558\uace0 \uc788\ub2e4."}),"\n",(0,s.jsx)(t.p,{children:"But you do believe it's important that newspapers survive?"}),"\n",(0,s.jsx)(t.p,{children:"\uadf8\ub7ec\ub098 \uc2e0\ubb38\uc0ac\ub4e4\uc774 \uc0b4\uc544\ub0a8\ub294 \uac74 \uc911\uc694\ud55c \ubb38\uc81c\ub77c\uace0 \uc0dd\uac01\ud558\uc9c0 \uc54a\ub294\uac00."}),"\n",(0,s.jsx)(t.p,{children:"Not only do we believe that, but I've been outspoken about it because I want everyone to get that. The fundamental question you're asking is why does Google not write large checks to newspapers? We're careful at Google with our money. We write large checks when we have a great strategy. And we don't yet have that strategy."}),"\n",(0,s.jsx)(t.p,{children:"\uadf8\ub807\ub2e4\uace0 \uc0dd\uac01\ud560 \ubfd0\ub9cc \uc544\ub2c8\ub77c \ubaa8\ub4e0 \uc0ac\ub78c\ub4e4\uc774 \uc774 \ubb38\uc81c\ub97c \uc54c\uc544\uc57c \ud55c\ub2e4\uace0 \uc0dd\uac01\ud574\uc11c \ub2e4\ub978 \uc0ac\ub78c\ub4e4\uc5d0\uac8c\ub3c4 \ub9d0\ud574 \uc654\ub2e4. \ub2f9\uc2e0\uc774 \ud55c \uadfc\ubcf8\uc801\uc778 \uc9c8\ubb38\uc740 \uad6c\uae00\uc774 \uc65c \uc2e0\ubb38\uc0ac\ub4e4\uc5d0\uac8c \ud22c\uc790\ub97c \ud558\uc9c0 \uc54a\ub290\ub0d0\ub294 \uac83 \uc544\ub2cc\uac00? \uc6b0\ub9ac\ub294 \uad6c\uae00 \uc11c\ube44\uc2a4\uc5d0 \ub3c8\uc744 \uc0ac\uc6a9\ud558\ub294 \uac83\uc5d0 \ub300\ud574 \ub9e4\uc6b0 \uc2e0\uc911\ud558\ub2e4. \uc6b0\ub9ac\ub294 \ud070 \uc804\ub7b5\uc774 \uc138\uc6cc\uc84c\uc744 \ub54c \ud22c\uc790\ub97c \ud558\ub294\ub370 \uc774 \uc0ac\uc548\uc5d0 \ub300\ud574\uc11c\ub294 \uc544\uc9c1 \uc804\ub7b5\uc744 \uac00\uc9c0\uace0 \uc788\uc9c0 \uc54a\ub2e4."}),"\n",(0,s.jsx)(t.p,{children:"What if the newspaper industry does go down?"}),"\n",(0,s.jsx)(t.p,{children:"\ub9cc\uc57d \uc2e0\ubb38\uc0b0\uc5c5\uc774 \uc1e0\ub77d\ud55c\ub2e4\uba74 \uc5b4\ub5bb\uac8c \ub420\uae4c?"}),"\n",(0,s.jsx)(t.p,{children:"To me this presents a real tragedy in the sense that journalism is a central part of democracy. And if it can't be funded because of these business problems, then that's a real loss in terms of voices and diversity. And I don't think bloggers make up the difference. The historic model of investigative journalists in any industry is something that is very fundamental. So the question is, what can you do about this? And a fair statement is, we're still looking for the right answer."}),"\n",(0,s.jsx)(t.p,{children:"\ub098\uc5d0\uac8c \uc2e0\ubb38\uc0b0\uc5c5 \uc1e0\ub77d\uc740 \uc800\ub110\ub9ac\uc998\uc774 \ubbfc\uc8fc\uc8fc\uc758\uc758 \uc911\uc2ec\uc774\ub77c\ub294 \uc778\uc2dd\uc5d0 \uc788\uc5b4\uc11c \uc9c4\uc815\ud55c \ube44\uadf9\uc774\ub2e4. \ub9cc\uc57d \ube44\uc988\ub2c8\uc2a4\uc801\uc778 \ubb38\uc81c \ub54c\ubb38\uc5d0 (\uc2e0\ubb38\uc0b0\uc5c5)\uc774 \ud22c\uc790\ubc1b\uc9c0 \ubabb\ud55c\ub2e4\uba74, \uc774\ub294 \uc5ec\ub7ec \uc758\uacac\uacfc \ub2e4\uc591\uc131\uc758 \uc190\uc2e4\uc744 \ucd08\ub798\ud558\uac8c \ub420 \uac83\uc774\ub2e4. \ub098\ub294 \ube14\ub85c\uac70\ub77c \ud560\uc9c0\ub77c\ub3c4 \ub2e4\ub974\uc9c0 \uc54a\uc744 \uac83\uc774\ub77c \uc0dd\uac01\ud55c\ub2e4. \uc5b4\ub5a0\ud55c \uc0ac\uc5c5\uc5d0\uc11c\ub3c4 \ud0d0\uc0ac \uc800\ub110\ub9ac\uc998\uc758 \uc5ed\uc0ac\uc801\uc778 \ubaa8\ub378\uc740 \ub9e4\uc6b0 \uae30\ubcf8\uc801\uc778 \uac83\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ubb38\uc81c\ub294 \uc5b4\ub5bb\uac8c \ud560 \uac83\uc774\ub0d0\ub294 \uac74\ub370, \uae30\ubcf8\uc801\uc73c\ub85c \uc6b0\ub9ac\ub3c4 \uc801\uc808\ud55c \ub2f5\uc744 \uce6e\uace0 \uc788\ub2e4\uace0 \ub9d0\ud560 \uc218 \ubc16\uc5d0 \uc5c6\ub2e4."}),"\n",(0,s.jsxs)(t.p,{children:["\uc6d0\ubb38 \ucd9c\ucc98 : ",(0,s.jsx)(t.a,{href:"http://money.cnn.com/2009/01/07/technology/lashinsky_google.fortune/index.htm?postversion=2009010711",children:"CNN Money - Eric Schmidt wishes Google could save newspapers - Jan. 7, 2009"}),(0,s.jsx)(t.br,{}),"\n\ubc88\uc5ed : ",(0,s.jsx)(t.a,{href:"http://blog.summerz.pe.kr/",children:"\uc368\uba38\uc988"})]}),"\n",(0,s.jsx)(t.p,{children:"\uad6c\uae00(\uc758 \uc5d0\ub9ad \uc288\ubbf8\uce20)\uac00 \uc0dd\uac01\ud558\ub294 \uc0ac\uc5c5 \ubc29\uc2dd \ubc0f \uc2e0\ubb38\uc0ac\ub97c \ubc14\ub77c\ubcf4\ub294 \uc2dc\uc120 \ub4f1\uc5d0 \ub300\ud574 \uc798 \ub098\ud0c0\ub098 \uc788\ub294 \uc778\ud130\ubdf0\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uad6c\uae00\uc740 \uad11\uace0 \ud68c\uc0ac\ub77c\uace0 \uc815\ud655\ud788 \ubabb\uc744 \ubc15\uace0 \uc788\uc8e0. \ud0d0\uc0ac \uc800\ub110\ub9ac\uc998\uc5d0 \ub300\ud55c \uac00\uce58\ub97c \ub192\uac8c \ud3c9\uac00\ud558\uba74\uc11c \uc800\ub110\ub9ac\uc998\uc740 \uae30\ubcf8\uc801\uc73c\ub85c \ube44\uc601\ub9ac\ub77c\ub294 \uc810\uc744 \uad6c\uae00\uacfc \ube44\uad50\ud558\ub294 \uc810\uc774 \uc778\uc0c1\uc801\uc785\ub2c8\ub2e4."}),"\n",(0,s.jsx)(t.p,{children:"\uc989, \uc0ac\uc5c5\uc801\uc73c\ub85c \ubcfc \ub54c, \uad11\uace0\ub294 \ubbf8\ub514\uc5b4\uc5d0 \ubd99\ub294\ub2e4\ub294 \uad00\uc810\uc5d0\uc11c \uad6c\uae00\uc740 \ubbf8\ub514\uc5b4\uac00 \ud544\uc694\ud55c \uac83\uc774\uaca0\uc9c0\uc694. \uadf8\ub7fc \uc720\ud29c\ube0c\ub294? \uad6c\uae00 \ub2e5\uc2a4\ub294? \uad6c\uae00 \ud06c\ub86c\uc740? \uc5ed\uc2dc \uc544\uc9c1 \ub5a0\uc624\ub974\uc9c0 \uc54a\uc740 \ucee4\ub2e4\ub780 \uc2dc\uc7a5\uc5d0 \ub300\ud55c \uadf8\ub9bc\uc744 \uadf8\ub9ac\uace0 \uc788\ub294 \uac83 \uac19\uc2b5\ub2c8\ub2e4."}),"\n",(0,s.jsx)(t.p,{children:"\ub610\ud55c \uc800 \uc5ed\uc2dc \uad6c\uae00\uc774 \uc9c1\uc811 \ubbf8\ub514\uc5b4\uac00 \ub420 \ud544\uc694\ub294 \uc5c6\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ubbf8\ub514\uc5b4\uac00 \ub418\uace0 \uc2f6\uc740 \uae30\uc5c5\uc740 \uad6c\uae00 \ub9d0\uace0\ub3c4 \ub9ce\uc774 \uc788\uc744\ud14c\ub2c8\uae4c\uc694. \ub2e4\ub9cc \uc5d0\ub9ad \uc288\ubbf8\uce20\uac00 \uc6b0\ub824\ud558\ub294 \ub300\ub85c \uc774\ub7ec\ud55c \uc800\ub110\ub9ac\uc998\uc774 \ubab0\ub77d\ud558\ub294 \uac83\uc740 \ubbfc\uc8fc\uc8fc\uc758\uc758 \uc704\uae30\ub77c\uace0 \ud560 \uc218 \uc788\uaca0\uc2b5\ub2c8\ub2e4."}),"\n",(0,s.jsx)(t.p,{children:"\uc6b0\ub9ac\ub098\ub77c\uc5d0\uc11c\ub294 \uc774\uc640\ub294 \ubc18\ub300\ub85c \uba40\uca61\ud55c \uc800\ub110\ub9ac\uc998\uc758 \uc5ed\ud560\uc744 \uc218\ud589\ud558\ub294 \ubc29\uc1a1\uc0ac\ub4e4\uc744 \ubabb\uc7a1\uc544 \uba39\uc5b4\uc11c \uc548\ub2ec\uc774 \ub098 \uc788\ub294 \uc0ac\ub78c\ub4e4\uc774 \ub9ce\uc774 \uc788\uc8e0. \uc608, \uc778\ud130\ub137\uc5d0 \uae00 \uc880 \uc62c\ub838\ub2e4\uace0 \uad6c\uc18d\ud558\ub294 \uc77c\uc774 \ubc8c\uc5b4\uc9c0\uace0 \uc788\ub294 2009\ub144\uc758 \ub300\ud55c\ubbfc\uad6d\uc5d0\uc11c \ub9d0\uc774\uc8e0."}),"\n",(0,s.jsx)(t.p,{children:"[from my mobile device, iPod Touch, partially]"})]})}function c(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453:(e,t,n)=>{n.d(t,{R:()=>r,x:()=>a});var s=n(296540);const o={},i=s.createContext(o);function r(e){const t=s.useContext(i);return s.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),s.createElement(i.Provider,{value:t},e.children)}}}]);